// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { HTMLAttributes } from "react";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import { getIconSize } from "../utils/commonUtils";

import "./StatusBadge.scss";
// Extend existing React interface Badge.
export interface StatusBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Identifying value for the badge.
   */
  id: string;
  /**
   * Determines the type of the badge: dot, counter, counter-long.
   */
  type?: "filled" | "outline";
  /**
   * Determines the colour palette of the badge.
   */
  colour?: "primary" | "secondary" | "tertiary" |  "success" | "warning" | "error" | "surface" |  "primary-soft" | "secondary-soft" | "tertiary-soft" |  "success-soft" | "warning-soft" | "error-soft" | "surface-soft";
  /**
   * Determines the shape of the badge.
   */
  shape?: "rounded" | "semi-rounded";
  /**
   * Determines the size of the button: small, medium, large ,x-large.
   */
  size?: "small" | "medium" | "large";
  /**
   * Determines the label of the badge.
   */
  label?: string;
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;  
  /**
   * SVG React Component to be displayed as the badge icon.
   */
  leadingIcon?: keyof typeof SvgMpaIcon | string;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({
  id,
  type = "filled",
  colour = "primary",
  shape = "rounded",
  size = "medium",
  label ="status",  
  className,
  leadingIcon,
}) => {    
    const badgeClassName = [
      "mpa-status-badge",
      `status-badge-${type}`,
      `status-badge-${shape}`,
      `status-badge-${colour}`,
      `status-badge-${size}`,
      className,
    ].join(" ");
  
  const iconSize = getIconSize(size);

	return (      
      <span id={id} className={badgeClassName}>  
          {leadingIcon && 
            <span className="status-badge-icon">     
              {<MpaIcon iconName={leadingIcon} size={iconSize}/>}
            </span>} 
          {label}    
      </span>
	);
};

export default StatusBadge;
